package de.sebaro_ventures.design.designsystem

import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Row
import androidx.compose.foundation.layout.size
import androidx.compose.material3.Icon
import androidx.compose.runtime.Composable
import androidx.compose.runtime.ReadOnlyComposable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.semantics.contentDescription
import androidx.compose.ui.semantics.semantics
import de.sebaro_ventures.design.SebaroTheme
import de.sebaro_ventures.design.icons.SebaroIcons

/** The five tones of spec/02 §3.1, named as the CSS modifiers of sb-status. */
enum class SbStatusTone { Info, Neutral, Success, Danger, Warning }

/**
 * The glyph of a status when it is not the tone's own (spec/02 §3.1, §3.1a): Warning for „Konflikt“ (D92), Pending
 * for a counted rest „2 offen“ also in the neutral tone (D91 Z1a), Globe for „nur online“ (16 dp: info).
 */
enum class SbStatusGlyph { Progress, Clock, Success, Error, Pending, Warning, Globe }

/**
 * Status (spec/01 §1.5): the glyph in its status colour + the word in text, caption; a word that does not fit its place
 * wraps under itself beside the glyph, never cut (§14.3, D99 (1)). [word] = the state
 * word; null takes the tone's word from the table (läuft, geplant, erledigt, Fehler, offen). [small] = the 16 dp
 * glyph of notes, claim rows and check lists; else 20 dp (lists). [glyph] = another glyph than the tone's (null =
 * the tone's: progress, clock, success, error, pending); the colour stays the tone's.
 */
@Composable
fun SbStatus(
    tone: SbStatusTone,
    modifier: Modifier = Modifier,
    word: String? = null,
    small: Boolean = false,
    glyph: SbStatusGlyph? = null,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val (own, tint) = when (tone) {
        SbStatusTone.Info -> SbStatusGlyph.Progress to c.info
        SbStatusTone.Neutral -> SbStatusGlyph.Clock to c.textMuted
        SbStatusTone.Success -> SbStatusGlyph.Success to c.success
        SbStatusTone.Danger -> SbStatusGlyph.Error to c.danger
        SbStatusTone.Warning -> SbStatusGlyph.Pending to c.warning
    }
    val icon = when (glyph ?: own) {
        SbStatusGlyph.Progress -> if (small) SebaroIcons.Outline16.Progress else SebaroIcons.Outline20.Progress
        SbStatusGlyph.Clock -> if (small) SebaroIcons.Outline16.Clock else SebaroIcons.Outline20.Clock
        SbStatusGlyph.Success -> if (small) SebaroIcons.Filled16.Success else SebaroIcons.Filled.Success
        SbStatusGlyph.Error -> if (small) SebaroIcons.Filled16.Error else SebaroIcons.Filled.Error
        SbStatusGlyph.Pending -> if (small) SebaroIcons.Outline16.Pending else SebaroIcons.Outline20.Pending
        SbStatusGlyph.Warning -> if (small) SebaroIcons.Outline16.Warning else SebaroIcons.Outline20.Warning
        SbStatusGlyph.Globe -> if (small) SebaroIcons.Outline16.Info else SebaroIcons.Outline20.Globe
    }
    // §14.3, D99 (1): the word wraps (a word wider than its place is hyphenated), never cut; the glyph stays
    // centred beside the word's lines (one line looks as before)
    Row(
        modifier.semantics(mergeDescendants = true) {},
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(t.space.s1),
    ) {
        Icon(icon, contentDescription = null, tint = tint, modifier = Modifier.size(if (small) t.size.iconSm else t.size.iconMd))
        SbWrapText(sbStatusWord(tone, word), SebaroTheme.typography.caption, c.text, Modifier.weight(1f, fill = false))
    }
}

/** The word a status shows (SbStatus, SbListRow's status): [word], or the tone's word from the table. */
@Composable
@ReadOnlyComposable
internal fun sbStatusWord(tone: SbStatusTone, word: String?): String {
    if (word != null) return word
    val m = sbMessages()
    return when (tone) {
        SbStatusTone.Info -> m.statusRunning
        SbStatusTone.Neutral -> m.statusPlanned
        SbStatusTone.Success -> m.statusDone
        SbStatusTone.Danger -> m.statusFailed
        SbStatusTone.Warning -> m.statusOpen
    }
}
